<template><el-container class="shell"><el-aside width="232px"><div class="brand"><b>✦ SHOPRO</b><span>AI 厂商运营后台</span></div><el-menu :default-active="route.path" router background-color="#172033" text-color="#aeb9ce" active-text-color="#fff"><el-menu-item v-for="m in menus" :key="m.path" :index="m.path"><el-icon><component :is="m.icon"/></el-icon>{{m.name}}</el-menu-item></el-menu></el-aside><el-container><el-header><div><strong>{{title}}</strong><small> 工作台 / {{title}}</small></div><div class="top"><el-tag type="success">Demo 数据</el-tag><el-button circle :icon="Bell"/><span>{{auth.user?.name}}</span><el-button link @click="logout">退出</el-button></div></el-header><el-main><router-view/></el-main></el-container></el-container></template><script setup lang="ts">import {computed} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useAuthStore} from '@/stores/auth';import {Bell,DataAnalysis,User,VideoPlay,DocumentChecked,ShoppingBag,Setting} from '@element-plus/icons-vue';const route=useRoute(),router=useRouter(),auth=useAuthStore();const menus=[{path:'/dashboard',name:'运营总览',icon:DataAnalysis},{path:'/users',name:'用户与积分',icon:User},{path:'/jobs',name:'AI 任务中心',icon:VideoPlay},{path:'/contents',name:'内容审核',icon:DocumentChecked},{path:'/orders',name:'订单与套餐',icon:ShoppingBag},{path:'/system',name:'系统运营',icon:Setting}];const title=computed(()=>menus.find(x=>x.path===route.path)?.name||'运营总览');function logout(){auth.logout();router.push('/login')}</script>